def check():
    events=[]
    class Field:
     def __getitem__(self,key):
      events.append('get:'+key)
      return self
     def __format__(self,spec):
      with open('value') as stream:
       events.append('format:'+spec)
       return stream.read()
    cases=[('{0:>4}|{',['format:>4']),
           ('{0[a]!z}',['get:a']),
           ('{0[a]:{width:{width}}}',['get:a']),
           ('{0[missing}',[]),
           ('{0[é]🐍}',['get:é'])]
    for template,expected in cases:
     method=template.format
     for repeat in range(2):
      events.clear()
      try:method(Field(),width=4)
      except ValueError:pass
      else:raise AssertionError('deferred error missing')
      assert events==expected,(events,expected)
    events.clear()
    method='{0:9999999999999999999999999999d}'.format
    assert method(Field())=='ok'
    assert method(Field())=='ok'
    assert len(events)==2
    return 'ok'
assert check()=='ok'

def check():
    events=[]
    class Field:
     def __getitem__(self,key):
      events.append('get:'+key)
      return self
     def __format__(self,spec):
      with open('value') as stream:
       events.append('format:'+spec)
       return stream.read()
    cases=[('{v:>4}|{',['format:>4']),
           ('{v[a]!z}',['get:a']),
           ('{v[a]:{width:{width}}}',['get:a']),
           ('{v[missing}',[]),
           ('{v[é]🐍}',['get:é'])]
    for template,expected in cases:
     method=template.format_map
     for repeat in range(2):
      events.clear()
      try:method({'v':Field(),'width':4})
      except ValueError:pass
      else:raise AssertionError('deferred error missing')
      assert events==expected,(events,expected)
    events.clear()
    method='{v:9999999999999999999999999999d}'.format_map
    assert method({'v':Field()})=='ok'
    assert method({'v':Field()})=='ok'
    assert len(events)==2
    return 'ok'
assert check()=='ok'
